#define SCALE 2.0
const float K = 0.25;

vec3 palette(float t)
{
    return vec3(t, 0.0, 0.0);
}

float hash(vec2 p)
{
    return 0.2 * SCALE * 0.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(palette(K), hash(fragCoord));
}

#define SCALE 8.0
const float K = 0.5;

vec3 palette(float t)
{
    return vec3(0.0, t, 0.0);
}

float hash(vec2 p)
{
    return 0.5;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 a = texture(iChannel0, uv).rgb;
    fragColor = vec4(a + palette(K) + vec3(0.0, 0.0, hash(uv) * SCALE / 16.0), 1.0);
}
